import sys

def solve(n):
    results = []
    for i in range(n):
        for j in range(i + 1, n):
            if i + j == n - 1:
                results.append(0)
            elif i < j:
                results.append(1)
            else:
                results.append(-1)
    return results

input = sys.stdin.read().strip().split()
t = int(input[0])
index = 1
for _ in range(t):
    n = int(input[index])
    index += 1
    results = solve(n)
    print(" ".join(map(str, results)))
